using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ApexInstinctEffect", menuName = "Data/Battle/Effects/Cellarius/ApexInstinct Effect")]
public class ApexInstinctEffect : Effect
{
	[Header("Apex Instinct Influence")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private OmenLogic omenLogic;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return Smart.Format(base.localizationManager.GetLocalizedWheneverPlayAVirtue(), purifyAction.GetActionDescription(amount).LowercaseFirst());
	}

	public override int ActivateEffect(int amount, GameObject effectOwner)
	{
		omenLogic.ActivateOmen(purifyAction, amount, null, null);
		return amount;
	}
}
